G=load()

def ccs(g,bg):
    H,W=len(g),len(g[0]); seen=set(); res=[]
    for y in range(H):
        for x in range(W):
            if (y,x) not in seen and g[y][x]!=bg:
                st=[(y,x)]; cl=set()
                while st:
                    a,b=st.pop(); cl.add((a,b))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        p=(a+dy,b+dx)
                        if 0<=p[0]<H and 0<=p[1]<W and p not in seen and g[p[0]][p[1]]!=bg:
                            seen.add(p); st.append(p)
                res.append(sorted(cl)); seen|=cl
    return res

def variants(s, allow_rot=True, allow_flip=True):
    # returns list of sets of relative cells
    res=set()
    def add(v):
        ns={(y,x) for y,x in v}
        if not any(n in res for n in ns): res.add(ns)
    v=[set(s)]
    if not allow_rot:
        pass
    else:
        cur=[v[0]]
        for _ in range(3):
            nxt=[]
            for s2 in cur:
                s3={rot90(y,x) for y,x in s2}
                s4={flip(y,x) for y,x in s2}
                s5={flip(rot90(y,x)) for y,x in s2}
                nxt.append(s3); nxt.append(s4); nxt.append(s5)
            if nxt: cur=nxt
            res.update({frozenset(s) for s in nxt})
    return [frozenset(s) for s in res]

def rot90(y,x): return (x,-y)
def flip(y,x): return (-y,x)

def solve(j, allow_rot=True):
    gi=G[f'Demo pair {j} input']; go=G[f'Demo pair {j} output']
    bg=Counter(x for r in gi for x in r).most_common(1)[0][0]
    cs=ccs(gi,bg)
    # noise: colors whose all comps are size 1
    ccounts=Counter(map(int,(gi[a][b] for a,b in c) for c in cs))
    sizes=Counter(len(c) for c in cs)
    print('demo',j,'bg',bg,'sizes',dict(sizes),'per-comp colors:',ccounts)
    noise_colors=[c for c,s in dict(sizes).items() if s==1]
    # fragments: split comps by color
    frags=[]
    for c in cs:
        cols=sorted(set(gi[a][b] for a,b in c))
        for col in cols:
            fr=[(a,b) for a,b in c if gi[a][b]==col]
            if len(fr)>1 or (len(fr)==1 and col not in noise_colors):
                frags.append(frozenset(fr))
    print('fragments:',[(len(f),sum(1 for x in f if True)) for f in frags])
    outmask=frozenset((y,x) for y in range(len(go)) for x in range(len(go[0])) if go[y][x]!=bg)
    def placings(f,H,W):
        h=max(y for y,x in f)-min(y for y,x in f)+1
        w=max(x for y,x in f)-min(x for y,x in f)+1
        for ty in range(H-h+1):
            for tx in range(W-w+1):
                yield frozenset((y+ty,x+tx) for y,x in f)
    sol=[]
    # order: largest first
    order=sorted(range(len(frags)), key=lambda i:-len(frags[i]))
    used=set()
    idx=order[0]
    # backtrack
    F=[frags[i] for i in order]
    def bt(k,cov,moved):
        nonlocal sol
        if cov==outmask:
            if moved: sol.append([moved.copy()])
            return
        f=F[k]; ph=len(outmask)
        # limit placements by bounding box fit
        hs=max(y for y,x in f)-min(y for y,x in f)+1; ws=max(x for y,x in f)-min(x for y,x in f)+1
        if hs>ph or ws>ph//2: return
        for p in placings(f,len(go),len(go[0])):
            if not p.isdisjoint(cov): continue
            bt(k+1,cov|p,moved+[p])
    bt(0,frozenset(),[])
    print('found',len(sol))
    return sol,frags,outmask

